from pathlib import Path
from PIL import Image
import json, html, zipfile, shutil

R=Path(__file__).resolve().parents[1]
D=R/'illustrative-concepts'
for p in D.glob('*.png'):
    if Image.open(p).format=='JPEG': p.rename(p.with_suffix('.jpg'))
routes=[
 {'slug':'shared-handi','title':'The Shared Handi','theme':'Odisha community · contemporary folk-inspired', 'meaning':'Two people cradle one handi. Their curved arms embrace the vessel; rising rice turns the shared meal into the centre of the symbol.', 'promise':'A generous meal, made to share.', 'personality':'Grounded, generous, sociable.', 'palette':[('Earth red','#A23D32','Pot and warm primary identity'),('Forest','#254C3B','People, lettering and information'),('Ochre','#D6A64D','Rice and small accents'),('Ivory','#FFF7E8','Main background')], 'grammar':'Use spare human gestures, rice plants and vessels to show preparing and sharing a meal. Keep a simple horizontal storytelling band on packaging; leave the main logo uncluttered.', 'boundary':'A contemporary folk-inspired proposal. It is not labelled authentic Saura, Warli or an artisan-made identity. The stock reference is inspiration only and has not been reproduced.', 'type':'Sturdy, approachable sans lettering; a plain sans-serif for dish information.', 'use':'Strongest route for a local, warm identity with scope for illustrated walls, bags and menus.', 'source':'https://kruticoffee.com/pages/about-us', 'source_name':'Kruti Coffee — official story'},
 {'slug':'garden-handi','title':'The Dum Garden','theme':'Mughal botanical-inspired · aroma & abundance', 'meaning':'A handi grows into a balanced flowering garden. The pot identifies cooking; the rising grains and botanical rhythm suggest layers of aroma.', 'promise':'Aromatic layers, generously served.', 'personality':'Expressive, composed, abundant.', 'palette':[('Aubergine','#4D2445','Pot, typography and anchor colour'),('Coral','#CE6B4F','Floral accent'),('Ochre','#D3A749','Rice and leaf accents'),('Ivory','#FFF6E7','Main background')], 'grammar':'Extend the logo’s flower-and-leaf forms into generous botanical borders and large cropped panels. Use a quiet label field so floral detail never competes with dish names.', 'boundary':'Mughal botanical painting is courtly art, rather than a tribal style. This is a modern interpretation of its floral rhythm, with no royal-recipe or historical-lineage claim.', 'type':'Softly flared display capitals with a simple sans-serif for menus and order information.', 'use':'Best for a richly illustrated packaging world with a more composed restaurant feel.', 'source':'https://www.metmuseum.org/art/collection/search/838376', 'source_name':'The Met — Mughal composite flower'},
 {'slug':'dum-host','title':'The Dum Keeper','theme':'Modern illustrative mascot · care & aroma', 'meaning':'A cook holds a handi close, with the face and aroma shaped through negative space. The gesture communicates care and anticipation of the meal.', 'promise':'Good food, warmly served.', 'personality':'Personable, confident, welcoming.', 'palette':[('Indigo','#293C5A','Host silhouette and primary type'),('Saffron','#D99C38','Pot, rice and warm accents'),('Cream','#FFF7E8','Negative space and main background')], 'grammar':'Use the host as a recognisable recurring character on labels and social posts. Supporting illustrations can show serving and sharing; keep the face, pot and main pose consistent.', 'boundary':'An original illustrated host. The supplied chef references informed negative-space simplicity; their specific silhouettes, moustaches and hats are not the identity.', 'type':'Rounded sans lettering with a clear functional sans-serif for menu copy.', 'use':'Best for immediate food-service recognition and a compact, friendly symbol.', 'source':'research/illustrative-directions-research.md','source_name':'Research and reference interpretation'}
]
CSS='''*{box-sizing:border-box}body{margin:0;background:#fff9ef;color:#302d29;font:16px/1.65 Arial,sans-serif}main{max-width:1240px;margin:auto;padding:0 32px 70px}nav{display:flex;gap:24px;flex-wrap:wrap;padding:22px 0;border-bottom:1px solid #d9cdbd}a{color:var(--ink,#943d31);text-underline-offset:4px}header{padding:58px 0 36px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;font-weight:bold}h1{font:normal clamp(42px,6vw,78px)/1.05 Georgia,serif;letter-spacing:-1px;color:var(--ink,#943d31);margin:20px 0}h2{font:normal 36px/1.15 Georgia,serif;color:var(--ink,#943d31)}h3{line-height:1.3}p{max-width:780px}.lead{font-size:21px;max-width:750px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}img{display:block;width:100%;height:auto}figure{margin:0}figcaption,.small{font-size:13px;color:#6a6259;margin-top:12px}section{border-top:1px solid #d9cdbd;padding:40px 0;margin-top:24px}.palette{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.swatch{height:90px;border:1px solid #dbd0c0;margin-bottom:14px}.palette p{font-size:13px}.panel{background:#eee6d8;padding:28px}.button{display:inline-block;padding:12px 18px;background:var(--ink,#943d31);color:#fff9ef;text-decoration:none;margin:14px 0}article{min-width:0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;vertical-align:top;padding:16px 10px;border-bottom:1px solid #d9cdbd}li{margin:10px 0}.note{border-left:3px solid var(--ink,#943d31);padding:10px 24px}footer{padding-top:24px;border-top:1px solid #d9cdbd;font-size:13px}@media(max-width:750px){main{padding:0 20px 40px}.grid,.cards{grid-template-columns:1fr}.palette{grid-template-columns:1fr 1fr}header{padding-top:35px}h2{font-size:30px}}@media print{nav,.button{display:none}section{break-inside:avoid}}'''
def image(slug,kind,alt):
    p=D/f'{slug}-{kind}.jpg'; w,h=Image.open(p).size
    return f'<img src="illustrative-concepts/{p.name}" alt="{html.escape(alt)}" width="{w}" height="{h}" loading="lazy">'
def page(title,body,ink='#943d31'):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body style="--ink:{ink}"><main>{body}</main></body></html>'
for i,c in enumerate(routes,1):
    slug=c['slug']
    palette=''.join(f'<article><div class="swatch" style="background:{h}"></div><strong>{n}</strong><br><code>{h}</code><p>{role}</p></article>' for n,h,role in c['palette'])
    body=f'''<nav><a href="brand-review.html">← Compare concepts</a><a href="#application">Packaging</a><a href="#system">Brand system</a><a href="brand-history.html">Earlier work</a></nav><header><div class="eyebrow">Illustrative identity / Concept {i:02} / Dum E Odisha</div><h1>{c['title']}</h1><p class="lead">{c['theme']}</p><p>{c['use']}</p></header><div class="grid"><figure>{image(slug,'logo',c['title']+' illustrative Dum E Odisha logo')}</figure><div><h2>The story in the symbol.</h2><p>{c['meaning']}</p><p><strong>Brand name:</strong> Dum E Odisha.<br><strong>Tagline:</strong> Flavour in Every Layer.</p><p><strong>Positioning:</strong> A biryani specialist bringing flavour and variety to everyday cravings and shared meals.</p><p><strong>Personality:</strong> {c['personality']}<br><strong>Concept promise:</strong> {c['promise']}</p><a class="button" href="illustrative-concepts/{slug}-logo.jpg" download>Download logo study</a></div></div><section id="application"><div class="eyebrow">The illustration becomes a brand world</div><h2>From symbol to packaging.</h2><figure>{image(slug,'mockup',c['title']+' concept packaging with matching illustrated identity')}<figcaption>Nano Banana application concept. Packaging, food, materials and scene are illustrative. Any menu details or prices visible in a mockup are sample content, not a confirmed menu; no manufacturing specification is implied.</figcaption></figure><p>{c['grammar']}</p></section><section id="system"><h2>A palette with clear roles.</h2><div class="palette">{palette}</div><p class="small">HEX colours are design targets. Generated raster tones may vary. Use the main colours consistently rather than changing the logo for every biryani flavour.</p></section><section><div class="grid"><div><h2>Words & typography.</h2><p>{c['type']} The generated lettering is artwork; no exact licensed font match is claimed.</p><p>Write the full name <strong>Dum E Odisha</strong>. Keep Dum and E visibly separate. “Biryani” is a category or product description, outside the brand name.</p><p>Voice: simple, welcoming and food-led. Example: “Find your favourite. Share a biryani.” Keep <em>Flavour in Every Layer.</em> as the shared tagline across these concept routes.</p></div><div class="panel"><h3>Working use rules</h3><ul><li>Lead with the illustration; keep the name readable beneath it.</li><li>Preserve the source composition, colours and proportions.</li><li>Keep at least a symbol-head or blossom width of clear space around the full logo.</li><li>Use plain fields behind the logo; place larger illustration on separate panels.</li><li>Do not place intricate storytelling inside the small symbol.</li><li>Actual-size legibility, small-format simplification and one-ink versions require a further artwork pass after a route is chosen.</li></ul></div></div></section><section><h2>Reference, interpreted.</h2><p>{c['boundary']}</p><p><a href="{c['source']}">{c['source_name']}</a> · <a href="research/illustrative-directions-research.md">Full research notes</a></p></section><footer>Concept exploration, revision 07. All new artwork generated through Nano Banana MCP. High-resolution JPEG studies with opaque backgrounds; no editable vector, transparent master or print dieline is included.</footer>'''
    (R/f'brand-{slug}.html').write_text(page('Dum E Odisha — '+c['title'],body,c['palette'][0][1]))
cards=''.join(f'<article>{image(c["slug"],"logo",c["title"]+" concept logo")}<div class="eyebrow">Concept {i:02}</div><h2>{c["title"]}</h2><p>{c["theme"]}</p><p>{c["meaning"]}</p><a class="button" href="brand-{c["slug"]}.html">Explore this brand guide →</a></article>' for i,c in enumerate(routes,1))
hub='''<nav><a href="#concepts">Three concepts</a><a href="brand-audit.html">Research & references</a><a href="brand-history.html">Earlier designs</a></nav><header><div class="eyebrow">Dum E Odisha / Illustrative identity exploration / Revision 07</div><h1>A story before a wordmark.</h1><p class="lead">Three different ways to make flavour, sharing and the cook visible in the logo.</p><p>The illustration now leads. Each route has its own meaning, palette, graphic language and packaging application, with DUM and E kept distinct in the full name.</p></header><div class="cards" id="concepts">'''+cards+'''</div><section><h2>Where I would take it.</h2><p><strong>The Shared Handi</strong> is the strongest fit for an Odisha-rooted, welcoming brand: the human gesture and cooking vessel give the symbol a direct meaning, and the story has room to grow across bags, menus and walls.</p><p><strong>The Dum Garden</strong> offers the richest botanical illustration world. <strong>The Dum Keeper</strong> is the most direct character-led route. These are alternative identities, rather than colours to mix together.</p><p>All three retain the name <strong>Dum E Odisha</strong> and tagline <strong>Flavour in Every Layer.</strong></p></section><section><h2>Research behind the directions.</h2><p>Kruti Coffee suggests a useful principle: connect the brand’s visual story to a real origin and repeat it across the experience. For Dum E Odisha, the proposed subjects are sharing, cooking and aroma.</p><p>The Odisha route is contemporary folk-inspired illustration. The garden route draws on Mughal botanical painting. These are distinct references, with their context explained inside each guide.</p><p><a href="brand-audit.html">Read the research and reference interpretation →</a></p><a class="button" href="illustrative-concepts/dum-e-odisha-illustrative-concepts.zip" download>Download all three concept sets</a><p class="small">All new logo artwork and mockups created only with Nano Banana. Concepts are high-resolution raster studies; production masters follow after selection.</p></section><footer><a href="brand-history.html">All previous designs remain available</a> · <a href="brand-review-round06.html">Previous type-led guide</a></footer>'''
(R/'brand-review.html').write_text(page('Dum E Odisha — Three illustrative brand concepts',hub))
audit='''<nav><a href="brand-review.html">← Three illustrative concepts</a><a href="brand-history.html">History</a></nav><header><div class="eyebrow">Research & interpretation / Revision 07</div><h1>Meaning in the illustration.</h1><p class="lead">The supplied references combine a recognisable subject with a second idea through negative space. The new concepts use that principle to tell stories about a meal.</p></header><section><h2>Kruti Coffee</h2><p>Kruti’s official story describes its work with coffee farmers in Kindiriguda, Odisha. Its useful lesson here is the connection between the brand and a grounded story. Dum E Odisha’s brief supports flavour, variety and shared meals; no farmer partnership or social-impact programme has been assumed.</p><p><a href="https://kruticoffee.com/pages/about-us">Kruti Coffee — About us</a> · <a href="https://kruticoffee.com/pages/specialty-coffee-roastery-cafe">Roastery and café</a></p></section><section><h2>Odisha folk inspiration</h2><p>Saura is a specific Odisha tradition with ritual context. Warli is a different tradition associated with Maharashtra. The supplied red-and-white image is used as a broad visual reference, not copied or presented as evidence of Odisha provenance.</p><p>The Shared Handi uses original people, rice and cooking forms to tell a contemporary meal story. It is not presented as an authentic ritual painting or artisan collaboration.</p><p><a href="https://odisha.gov.in/en/odisha-tourism/paintings">Government of Odisha — Paintings</a></p></section><section><h2>Mughal botanical inspiration</h2><p>The Met documents floral compositions from the Mughal court, including a composite plant made from different botanical parts. The Dum Garden translates balanced stems and blossoms into a modern handi illustration. It makes no historical recipe claim.</p><p><a href="https://www.metmuseum.org/art/collection/search/838376">The Met — Composite Flower, circa 1630</a></p></section><section><h2>From the supplied symbol references</h2><p>The chef, animal and food symbols demonstrate bold silhouette, economy and negative-space storytelling. The new work uses original subjects and compositions. The watermarked stock artwork is not included in deliverables or recreated.</p><p><a href="research/illustrative-directions-research.md">Detailed source research</a> · <a href="research/illustrative-generation-prompts.json">Logo generation briefs</a> · <a href="docs/illustrative-philosophy.md">Design philosophy</a></p></section><section><h2>Review & practical limits</h2><p>Logo and mockup images are reviewed for name spelling, illustration meaning, palette and repeatability. The guide files are checked for local references and image integrity. No fresh browser-render test is claimed. The three routes remain concepts pending selection and production artwork.</p><p><a href="brand-audit-round06.html">Previous type-led design audit</a></p></section>'''
(R/'brand-audit.html').write_text(page('Dum E Odisha — Illustrative research',audit))
history=R/'brand-history.html'; s=history.read_text()
if 'id="round06"' not in s:
    block='<section id="round06"><h2>Revision 06 — type-led direction, superseded</h2><p>Preserved after the request for a more illustrative identity.</p><div class="grid"><article><img src="final-design/dum-e-odisha-final-logo.jpg" alt="Previous DUM E wordmark with separate E block"><a href="brand-review-round06.html">Previous guide and mockups</a></article><article><img src="final-design/dum-e-odisha-packaging-hero.jpg" alt="Previous packaging mockup"><a href="brand-audit-round06.html">Previous research</a></article></div></section>'
    s=s.replace('<section id="round05">',block+'<section id="round05">',1);history.write_text(s)
manifest={'brand_name':'Dum E Odisha','revision':'07','status':'Three illustrative concepts, no final route selected','tagline':'Flavour in Every Layer.','routes':routes,'artwork':'Nano Banana MCP only','files':[]}
for c in routes:
    for kind in ['logo','mockup']:
        p=D/f'{c["slug"]}-{kind}.jpg'; im=Image.open(p)
        manifest['files'].append({'file':p.name,'width':im.width,'height':im.height,'format':im.format})
(D/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(R/'docs/identity.json').write_text(json.dumps({'brand_name':'Dum E Odisha','revision':'07','status':'Illustrative concept exploration; no final route selected','tagline':'Flavour in Every Layer.','concept_manifest':'illustrative-concepts/manifest.json','previous_identity':'docs/identity-round06.json','guide':'brand-review.html'},indent=2)+'\n')
with zipfile.ZipFile(D/'dum-e-odisha-illustrative-concepts.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in D.glob('*.jpg'): z.write(p,p.name)
    z.write(D/'manifest.json','manifest.json')
    for p in [R/'research/illustrative-directions-research.md',R/'research/illustrative-generation-prompts.json',R/'research/illustrative-mockup-prompts.json',R/'docs/illustrative-philosophy.md']:
        z.write(p,p.name)
    z.writestr('README.txt','Dum E Odisha — Three illustrative concept routes\nEach pair contains logo and application mockup.\nTagline: Flavour in Every Layer.\nAll new visuals generated through Nano Banana MCP.\nThese are JPEG concept studies, not print-ready vector masters or dielines.\nDo not mix the routes into a single identity.\n')
print('Created three individual brand guides, comparison page, archive entry and download package.')
